/**
 * Background behaviour for the Automation module (Electron-specific, so kept out of the
 * testable service): system tray, "Start AI Hub with Windows" and desktop notifications.
 * Everything here is inactive unless Automation is enabled.
 */
import { app, Menu, nativeImage, Notification, Tray, type BrowserWindow } from 'electron'
import type { AutomationSettings } from '@shared/automation'
import { APP_NAME } from '@shared/defaults'

/** 32×32 tray icon (generated by tools/make-icon.mjs), embedded so packaged builds need no extra files. */
const TRAY_ICON =
  'data:image/png;base64,'

export const HIDDEN_ARG = '--hidden'

export class BackgroundManager {
  private tray?: Tray
  private quitting = false

  constructor(
    private readonly getWindow: () => BrowserWindow | null,
    private readonly showWindow: () => void
  ) {
    app.on('before-quit', () => {
      this.quitting = true
    })
  }

  /** Started with Windows (login item) → stay in the tray instead of opening a window. */
  static startedHidden(): boolean {
    return process.argv.includes(HIDDEN_ARG)
  }

  /** Should closing the window hide it to the tray instead of quitting? */
  keepRunningOnClose(s: AutomationSettings): boolean {
    return s.enabled && s.runInTray && !this.quitting
  }

  apply(s: AutomationSettings): void {
    const wantTray = s.enabled && s.runInTray
    if (wantTray && !this.tray) this.createTray()
    if (!wantTray && this.tray) {
      this.tray.destroy()
      this.tray = undefined
    }
    // Only packaged Windows/macOS builds register a login item (dev builds would register Electron itself).
    if (app.isPackaged && (process.platform === 'win32' || process.platform === 'darwin')) {
      const open = s.enabled && s.startWithWindows
      app.setLoginItemSettings({ openAtLogin: open, args: open ? [HIDDEN_ARG] : [] })
    }
  }

  private createTray(): void {
    this.tray = new Tray(nativeImage.createFromDataURL(TRAY_ICON))
    this.tray.setToolTip(`${APP_NAME} — automations running`)
    this.tray.setContextMenu(
      Menu.buildFromTemplate([
        { label: `Open ${APP_NAME}`, click: () => this.showWindow() },
        { type: 'separator' },
        {
          label: 'Quit',
          click: () => {
            this.quitting = true
            app.quit()
          }
        }
      ])
    )
    this.tray.on('click', () => this.showWindow())
  }

  notify(title: string, body: string): void {
    if (!Notification.isSupported()) return
    const n = new Notification({ title, body: body.slice(0, 250), silent: false })
    n.on('click', () => this.showWindow())
    n.show()
  }

  windowFocused(): boolean {
    const w = this.getWindow()
    return Boolean(w && w.isVisible() && w.isFocused())
  }
}
